// NODAL extension: Metro Planning Studio, simulated trains, learning lab & challenges.
const N = window.NODAL;
const { setBase, S, G, MODS, api, $, f2, short, tbl, mod, chart, axis, err, setOverlay, paint, setSrc, applyVis, LAY, LAYNAME, PAL, RM, clearTimers, idOf, stIn, fc, hv, posAt, lineUpTo, select, go, setMode } = N;
const SRC = ['access', 'anchors', 'plan', 'plan-st', 'towers', 'trains', 'wards', 'bus', 'mm'];
const POST = (path, body) => api(path, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
const debounce = (fn, ms) => { let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); }; };
