  m.addLayer({ id: 'access-fill', type: 'fill', source: 'access', paint: { 'fill-color': ['get', 'c'], 'fill-opacity': 0.42 } }, 'proposed');
  m.addLayer({ id: 'towers', type: 'fill-extrusion', source: 'towers', paint: { 'fill-extrusion-color': ['get', 'c'], 'fill-extrusion-height': ['get', 'h'], 'fill-extrusion-base': 0, 'fill-extrusion-opacity': 0.85 } }, 'st-inter');
