  m.addLayer({ id: 'plan-st-label', type: 'symbol', source: 'plan-st', minzoom: 11.5, layout: { 'text-field': ['get', 'name'], 'text-font': ['Noto Sans Bold'], 'text-size': 11, 'text-anchor': 'bottom', 'text-offset': [0, -1], 'text-optional': true }, paint: { 'text-color': '#8a3b00', 'text-halo-color': '#ffffff', 'text-halo-width': 1.8 } });
  m.addLayer({ id: 'anchors-label', type: 'symbol', source: 'anchors', layout: { 'text-field': ['get', 'name'], 'text-font': ['Noto Sans Bold'], 'text-size': 11, 'text-anchor': 'bottom', 'text-offset': [0, -1], 'text-optional': true }, paint: { 'text-color': '#3b1d60', 'text-halo-color': '#ffffff', 'text-halo-width': 1.8 } });
  m.addLayer({ id: 'pop-fill', type: 'fill', source: 'wards', paint: { 'fill-color': ['step', ['get', 'density'], '#fff7ec', 3000, '#fee8c8', 6000, '#fdd49e', 10000, '#fdbb84', 15000, '#fc8d59', 25000, '#d7301f'], 'fill-opacity': 0.55 } }, 'proposed');
  m.addLayer({ id: 'work-fill', type: 'fill', source: 'wards', paint: { 'fill-color': ['step', ['get', 'worker_density'], '#f7fbff', 1500, '#deebf7', 3000, '#c6dbef', 5000, '#9ecae1', 8000, '#4292c6', 12000, '#08519c'], 'fill-opacity': 0.55 } }, 'proposed');
  m.addLayer({ id: 'ward-line', type: 'line', source: 'wards', paint: { 'line-color': '#5b6b86', 'line-width': 0.6, 'line-opacity': 0.7 } }, 'proposed');
  m.addLayer({ id: 'bus-stops', type: 'circle', source: 'bus', minzoom: 11, paint: { 'circle-radius': ['interpolate', ['linear'], ['zoom'], 11, 1.5, 16, 5], 'circle-color': '#2f6bff', 'circle-opacity': 0.75 } }, 'st-inter');
  m.addLayer({ id: 'mm-casing', type: 'line', source: 'mm', layout: lc, paint: { 'line-color': '#0b1220', 'line-width': wz(7, 15) } }, 'st-inter');
  m.addLayer({ id: 'mm-line', type: 'line', source: 'mm', filter: ['!=', ['get', 'mode'], 'walk'], layout: lc, paint: { 'line-color': ['get', 'c'], 'line-width': wz(4, 10) } }, 'st-inter');
