let tLast = 0, tInfoAt = 0;
function tickTrains(now) { if (!T.on) return; const dt = Math.min(0.1, (now - tLast) / 1000); if (now - tLast > 33) { tLast = now; frame(dt); if (now - tInfoAt > 250) { tInfoAt = now; trainInfo(); } } requestAnimationFrame(tickTrains); }
