  <div class="row"><button class="b p" id="tp">❚❚ Pause</button><button class="b" id="tr">Reset</button><select id="tsp" style="width:auto"><option value="1">1× real time</option><option value="10">10×</option><option value="30" selected>30×</option><option value="100">100×</option></select></div>
